type Join<Prefix extends string, Key extends string> = Prefix extends "" ? Key : `${Prefix}.${Key}`;
type LeafKeys<T, Prefix extends string = ""> = {
  [Key in keyof T & string]: T[Key] extends string ? Join<Prefix, Key> : LeafKeys<T[Key], Join<Prefix, Key>>;
}[keyof T & string];

export type TranslationKey = LeafKeys<typeof vi>;
